#include <bits/stdc++.h>
using namespace std;
const int MAXN = 15000;
struct Edge {
    int to, cap, flow, cost;
};
vector<Edge> e;
vector<int> adj[MAXN];
long long ans, dist[MAXN];
int n, m, k, c, d, parent[MAXN], parent_edge[MAXN], in_queue[MAXN], src = 9998, sink = 9999;

void add_edge(int x, int y, int cap, int cost) {
    adj[x].push_back(e.size());
    e.push_back({y, cap, 0, cost});
    adj[y].push_back(e.size());
    e.push_back({x, 0, 0, -cost});
}

void push_rebel() {
    fill(dist, dist + 10000, (long long)1e18);
    fill(parent, parent + 10000, -1);
    fill(parent_edge, parent_edge + 10000, -1);
    fill(in_queue, in_queue + 10000, 0);
    dist[src] = 0;
    queue<int> q;
    q.push(src);
    in_queue[src] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;
        for (int idx : adj[u]) {
            if (!(e[idx].cap - e[idx].flow)) continue;
            int cost = e[idx].cost, v = e[idx].to;
            if (dist[v] > dist[u] + cost) {
                dist[v] = dist[u] + cost;
                parent[v] = u;
                parent_edge[v] = idx;
                if (!in_queue[v]) {
                    in_queue[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    int cur = sink;
    while (cur != src) {
        e[parent_edge[cur]].flow++;
        e[parent_edge[cur] ^ 1].flow--;
        cur = parent[cur];
    }
    ans += dist[sink];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m >> k >> c >> d;
    int x, y;
    for (int i = 1; i <= k; i++) {
        cin >> x;
        x--;
        add_edge(src, x, 1, 0);
    }
    for (int i = 1; i <= 101; i++)
        add_edge((i - 1) * n, sink, k, (i - 1) * c);
    for (int i = 1; i <= m; i++) {
        cin >> x >> y;
        x--; y--;
        for (int i = 1; i <= 100; i++)
            for (int j = 1; j <= k; j++) {
                add_edge(x + (i - 1) * n, y + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                add_edge(y + (i - 1) * n, x + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
            }
    }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= 100; j++)
            add_edge(i - 1 + (j - 1) * n, i - 1 + (j - 1) * n + n, k, 0);
    for (int i = 1; i <= k; i++) push_rebel();
    cout << ans << '\n';
    return 0;
}
